import { operation } from "@tinker/core";

import { drizzleOrm } from "~/components/database/index.server";
import { transaction } from "~/components/database/index.server";
import { readExecution } from "~/components/sync";
import { eventHistory, execution } from "~/components/sync/index.server";

import type { Errors } from "@/demo/errors";

import { counter } from "./sync.schema.server";

export const incrementCounter = operation({
  label: "incrementCounter",
  input: readExecution,
  depends: { orm: drizzleOrm, tx: transaction, history: eventHistory },
  run: async ({ orm, tx, history }, { input, raise }) => {
    const { eq, sql } = orm;

    await history.lock(tx, "public");
    if (await history.find(tx, input.executionId, "public")) {
      return { executionId: input.executionId };
    }

    await tx.insert(execution).values({ id: input.executionId, stream: "public" });
    await tx.insert(counter).values({ id: 1 }).onConflictDoNothing();

    const row = (
      await tx
        .update(counter)
        .set({ value: sql`${counter.value} + 1` })
        .where(eq(counter.id, 1))
        .returning()
    ).at(0);
    if (!row) {
      return raise("StreamMissing", {} satisfies Errors.Payload<"StreamMissing">);
    }

    await history.append(tx, "public", input.executionId, [
      { kind: "change", change: { kind: "counter", value: row.value } },
      { kind: "result", result: { kind: "complete", action: "counter" } },
    ]);

    return { executionId: input.executionId };
  },
});

import { operation, resource } from "@tinker/core";

import { user } from "~/components/auth/index.server";
import { principal } from "~/components/auth/index.server";
import { drizzleOrm } from "~/components/database/index.server";
import { database } from "~/components/database/index.server";
import { sendMail } from "~/components/mail/index.server";
import { readExecution, readRetry } from "~/components/sync";
import type { Sync } from "~/components/sync";
import { eventHistory, execution } from "~/components/sync/index.server";

import { readProfileCommand } from "@/demo/contracts/commands";
import { profileRefusal, readProfileInput } from "@/demo/contracts/profile-contract";
import type { Profile } from "@/demo/contracts/profile-contract";
import { readFeatureResult } from "@/demo/contracts/sync";
import type { Errors } from "@/demo/errors";

import { currentUser } from "./auth.server";

export const readProfile = operation({
  label: "readProfile",
  depends: { orm: drizzleOrm, principal, database },
  run: async ({ orm, principal, database }): Promise<Profile.Value | null> => {
    const { eq } = orm;
    if (principal === null) return null;
    return (
      (
        await database
          .select({
            id: user.id,
            name: user.name,
            email: user.email,
            emailVerified: user.emailVerified,
          })
          .from(user)
          .where(eq(user.id, principal.id))
      ).at(0) ?? null
    );
  },
});

/** Mail runs after commit and outside a database lock; only its final event needs a transaction. */
const notifyProfile = operation({
  label: "notifyProfile",
  input: readExecution,
  depends: { orm: drizzleOrm, database, history: eventHistory, send: sendMail },
  run: async ({ orm, database, history, send }, { input, raise }) => {
    const { eq } = orm;
    const stored = (
      await database.select().from(execution).where(eq(execution.id, input.executionId))
    ).at(0);
    if (!stored?.notification) {
      return raise("RetryNotAvailable", {} satisfies Errors.Payload<"RetryNotAvailable">);
    }
    if (stored.result) return;

    const sent = await send.settle({ rawInput: stored.notification });
    const result: Sync.Result =
      sent.status === "success"
        ? { kind: "complete", action: "profile", profileId: stored.stream }
        : {
            kind: "partial",
            action: "profile",
            profileId: stored.stream,
            notification: {
              kind: "failed",
              message: "Name saved; notification failed. You can retry the notification.",
            },
          };

    await database.transaction(async (tx) => {
      await history.lock(tx, stored.stream);
      const latest = await history.find(tx, input.executionId, stored.stream);
      if (latest?.result) return;
      await history.append(tx, stored.stream, input.executionId, [{ kind: "result", result }]);
    });
  },
});

/** One process owner coalesces duplicate requests; this is not a cross-process SMTP guarantee. */
const notificationWork = resource({
  label: "profile.notificationWork",
  depends: { finish: notifyProfile },
  factory: ({ finish }, { log, defer }) => {
    const running = new Map<string, Promise<void>>();
    defer(async () => {
      await Promise.all(running.values());
    });
    return {
      finish(executionId: string) {
        if (running.has(executionId)) return;
        const completed = finish.settle({ input: { executionId } }).then((result) => {
          running.delete(executionId);
          if (result.status !== "success") {
            log.error("profile.notification.failed", { executionId, status: result.status });
          }
        });
        running.set(executionId, completed);
      },
    };
  },
});

export const saveProfile = operation({
  label: "saveProfile",
  input: readProfileCommand,
  depends: {
    orm: drizzleOrm,
    currentUser,
    database,
    history: eventHistory,
    notify: notificationWork,
  },
  run: async ({ orm, currentUser, database, history, notify }, { input, clock, raise }) => {
    const parsed = readProfileInput.safeParse(input.profile);
    if (!parsed.success) {
      return raise("BadInput", { reason: profileRefusal } satisfies Errors.Payload<"BadInput">);
    }
    const profile = parsed.data;
    const { eq } = orm;

    await database.transaction(async (tx) => {
      await history.lock(tx, currentUser.id);
      if (await history.find(tx, input.executionId, currentUser.id)) return;

      const saved = (
        await tx
          .update(user)
          .set({ name: profile.name, updatedAt: new Date(clock.currentTimeMillis()) })
          .where(eq(user.id, currentUser.id))
          .returning({
            id: user.id,
            name: user.name,
            email: user.email,
            emailVerified: user.emailVerified,
          })
      ).at(0);
      if (!saved) {
        return raise("SignInRequired", {} satisfies Errors.Payload<"SignInRequired">);
      }

      await tx.insert(execution).values({
        id: input.executionId,
        stream: currentUser.id,
        notification: {
          to: saved.email,
          subject: "Your profile was updated",
          text: `Your saved name is ${saved.name}.`,
        },
      });

      await history.append(tx, currentUser.id, input.executionId, [
        { kind: "change", change: { kind: "profile", profile: saved } },
      ]);
    });

    notify.finish(input.executionId);
    return { executionId: input.executionId };
  },
});

export const retryNotification = operation({
  label: "retryNotification",
  input: readRetry,
  depends: {
    currentUser,
    database,
    history: eventHistory,
    notify: notificationWork,
  },
  run: async ({ currentUser, database, history, notify }, { input, raise }) => {
    await database.transaction(async (tx) => {
      await history.lock(tx, currentUser.id);
      if (await history.find(tx, input.executionId, currentUser.id)) return;

      const previous = await history.find(tx, input.previousExecutionId, currentUser.id);
      if (!previous?.notification || !previous.result) {
        return raise("RetryNotAvailable", {} satisfies Errors.Payload<"RetryNotAvailable">);
      }
      const result = readFeatureResult.safeParse(previous.result);
      if (!result.success || result.data.kind !== "partial") {
        return raise("RetryNotAvailable", {} satisfies Errors.Payload<"RetryNotAvailable">);
      }

      await tx.insert(execution).values({
        id: input.executionId,
        stream: currentUser.id,
        notification: previous.notification,
      });
    });

    notify.finish(input.executionId);
    return { executionId: input.executionId };
  },
});

