import { operation } from "@tinker/core";

import { drizzleOrm } from "~/components/database/index.server";
import { database, transaction } from "~/components/database/index.server";
import type { Sync } from "~/components/sync";
import { eventHistory, execution } from "~/components/sync/index.server";

import { readTodoCommand } from "@/demo/contracts/commands";
import { readTodoChange, todoRefusal } from "@/demo/contracts/todos-contract";
import type { Todos } from "@/demo/contracts/todos-contract";
import type { Errors } from "@/demo/errors";

import { currentUser } from "./auth.server";
import { todo } from "./todos.schema.server";

export const listTodos = operation({
  label: "listTodos",
  depends: { orm: drizzleOrm, currentUser, database },
  run: ({ orm, currentUser, database }): Promise<Todos.Row[]> => {
    const { asc, eq } = orm;
    return database
      .select({ id: todo.id, title: todo.title, done: todo.done })
      .from(todo)
      .where(eq(todo.ownerId, currentUser.id))
      .orderBy(asc(todo.id));
  },
});

export const changeTodo = operation({
  label: "changeTodo",
  input: readTodoCommand,
  depends: { orm: drizzleOrm, currentUser, tx: transaction, history: eventHistory },
  run: async ({ orm, currentUser, tx, history }, { input, raise }) => {
    const parsed = readTodoChange.safeParse(input.change);
    if (!parsed.success) {
      return raise("BadInput", { reason: todoRefusal } satisfies Errors.Payload<"BadInput">);
    }
    const change = parsed.data;
    const { and, asc, eq } = orm;

    await history.lock(tx, currentUser.id);
    if (await history.find(tx, input.executionId, currentUser.id)) {
      return { executionId: input.executionId };
    }

    let changed = true;
    if (change.kind === "add") {
      await tx.insert(todo).values({ ownerId: currentUser.id, title: change.title });
    } else {
      const owned = and(eq(todo.id, change.id), eq(todo.ownerId, currentUser.id));
      const row = (await tx.select().from(todo).where(owned)).at(0);
      if (!row) {
        return raise("TodoMissing", {} satisfies Errors.Payload<"TodoMissing">);
      }
      if (change.kind === "delete") await tx.delete(todo).where(owned);
      else if (row.done !== change.done) {
        await tx.update(todo).set({ done: change.done }).where(owned);
      } else changed = false;
    }

    await tx.insert(execution).values({ id: input.executionId, stream: currentUser.id });

    const payloads: Sync.Payload[] = [];
    if (changed) {
      const rows = await tx
        .select({ id: todo.id, title: todo.title, done: todo.done })
        .from(todo)
        .where(eq(todo.ownerId, currentUser.id))
        .orderBy(asc(todo.id));
      payloads.push({ kind: "change", change: { kind: "todos", rows } });
    }

    payloads.push({ kind: "result", result: { kind: "complete", action: "todo" } });
    await history.append(tx, currentUser.id, input.executionId, payloads);

    return { executionId: input.executionId };
  },
});

import { z } from "zod";

/** The profile body: one execution ID, and the profile input `saveProfile` reads. */
export const readProfileCommand = z
  .object({ executionId: z.uuid(), profile: z.unknown() })
  .strict();

/** The todo body: one execution ID, and the change `changeTodo` reads. */
export const readTodoCommand = z.object({ executionId: z.uuid(), change: z.unknown() }).strict();

import { z } from "zod";

export const credentials = z.object({
  mode: z.enum(["signup", "signin"]),
  name: z.string().max(80),
  email: z.email(),
  password: z.string().min(8),
});

import { z } from "zod";

export declare namespace Profile {
  type Value = { id: string; name: string; email: string; emailVerified: boolean };
  type Input = { name: string };
}

const profileInput = z.object({ name: z.string().trim().min(1).max(80) }).strict();

/** The name a profile save accepts; the operation that parses it raises the refusal. */
export const readProfileInput = profileInput;

/** The BadInput reason for a name the contract refuses. */
export const profileRefusal = "Use a name with 1 to 80 letters.";

import { z } from "zod";

import {
  eventEnvelope,
  snapshotEnvelope,
  batchEnvelope,
  bootstrapEnvelope,
} from "~/components/sync";

export declare namespace FeatureSync {
  type Change = z.infer<typeof change>;
  type Result = z.infer<typeof result>;
  type Public = z.infer<typeof snapshot>["public"];
  type Private = NonNullable<z.infer<typeof snapshot>["private"]>;
}

const profileRecord = z.object({
  id: z.string(),
  name: z.string(),
  email: z.string(),
  emailVerified: z.boolean(),
});

const todoRecord = z.object({ id: z.number(), title: z.string(), done: z.boolean() });

const result = z.union([
  z.object({ kind: z.literal("complete"), action: z.enum(["counter", "todo"]) }),
  z.object({ kind: z.literal("complete"), action: z.literal("profile"), profileId: z.string() }),
  z.object({
    kind: z.literal("partial"),
    action: z.literal("profile"),
    profileId: z.string(),
    notification: z.object({ kind: z.literal("failed"), message: z.string() }),
  }),
  z.object({
    kind: z.literal("failed"),
    action: z.enum(["counter", "todo", "profile"]),
    message: z.string(),
  }),
]);

const change = z.discriminatedUnion("kind", [
  z.object({ kind: z.literal("counter"), value: z.number() }),
  z.object({ kind: z.literal("profile"), profile: profileRecord }),
  z.object({ kind: z.literal("todos"), rows: z.array(todoRecord) }),
]);

const event = eventEnvelope.extend({
  payload: z.discriminatedUnion("kind", [
    z.object({ kind: z.literal("change"), change }),
    z.object({ kind: z.literal("result"), result }),
  ]),
});

const snapshot = snapshotEnvelope.extend({
  public: z.object({
    stream: z.literal("public"),
    revision: z.number().int().min(0),
    value: z.number(),
  }),
  private: z
    .object({
      stream: z.string(),
      revision: z.number().int().min(0),
      profile: profileRecord,
      todos: z.array(todoRecord),
    })
    .nullable(),
});

export const readSnapshot = snapshot;
const bootstrapInput = bootstrapEnvelope.extend({ snapshot });
export const readBootstrap = bootstrapInput;

const batchInput = batchEnvelope.extend({
  events: z.array(event),
});

export const readBatch = batchInput;

export const streamMessage = z.discriminatedUnion("kind", [
  z.object({ kind: z.literal("changes"), events: z.array(event).max(100) }),
  z.object({ kind: z.literal("account-change") }),
]);

export const readFeatureResult = result;
export const readFeatureEvents = z.array(event);

/** This app fills the base's open registry with its own bodies. */
declare module "~/components/sync" {
  interface Register {
    change: FeatureSync.Change;
    result: FeatureSync.Result;
    public: FeatureSync.Public;
    private: FeatureSync.Private;
  }
}

import { z } from "zod";

export declare namespace Todos {
  type Row = { id: number; title: string; done: boolean };
  type Change = z.infer<typeof todoChange>;
}

const todoChange = z.discriminatedUnion("kind", [
  z.object({ kind: z.literal("add"), title: z.string().trim().min(1).max(200) }).strict(),
  z
    .object({
      kind: z.literal("setDone"),
      id: z.number().int().positive().max(2_147_483_647),
      done: z.boolean(),
    })
    .strict(),
  z
    .object({ kind: z.literal("delete"), id: z.number().int().positive().max(2_147_483_647) })
    .strict(),
]);

/** The change a todo save accepts; the operation that parses it raises the refusal. */
export const readTodoChange = todoChange;

/** The BadInput reason for a change the contract refuses. */
export const todoRefusal = "Use a title with 1 to 200 characters and a valid todo change.";

import type { Errors as BaseErrors } from "~/components/errors";

export declare namespace Errors {
  type Payloads = {
    NotificationFailed: Record<string, never>;
    TodoMissing: Record<string, never>;
    SignInRequired: Record<string, never>;
    BadInput: { reason: string };
    Rollback: Record<string, never>;
    RetryNotAvailable: Record<string, never>;
    StoredDataInvalid: Record<string, never>;
    AuthFailed: { message: string };
  };
  type Name = keyof Payloads | BaseErrors.Name;
  type Payload<N extends Name> = N extends keyof Payloads
    ? Payloads[N]
    : N extends BaseErrors.Name
      ? BaseErrors.Payloads[N]
      : never;
  type Of<N extends Name> = Error & { kind: N; payload: Payload<N> };
}

/**
 * @param kind - From the failing caller; why: choose the managed error.
 * @param payload - From the failing caller; why: keep facts for that error.
 */
export function raise<N extends Errors.Name>(kind: N, payload: Errors.Payload<N>): never {
  throw Object.assign(new Error(kind), { kind, payload });
}

/**
 * @param error - From a caught failure; why: narrow its payload.
 * @param kind - From the caller; why: select the expected error.
 */
export function isError<N extends Errors.Name>(error: unknown, kind: N): error is Errors.Of<N> {
  return error instanceof Error && "kind" in error && error.kind === kind;
}

import { resource } from "@tinker/core";

import type { Sync } from "~/components/sync";

import { profile, todos, counter, nameDraft, profileResult } from "./state";

/** Saved records have one publisher; drafts belong to the local editor. */
export const records = resource({
  label: "records",
  depends: {
    profile: profile.controller,
    todos: todos.controller,
    counter: counter.controller,
    draft: nameDraft.controller,
    result: profileResult.controller,
  },
  factory: ({ profile, todos, counter, draft, result }): Sync.Records => ({
    resetPrivate() {
      profile.set(null);
      todos.set([]);
      draft.set(undefined);
      result.set(null);
    },
    bootstrapPublic(value: Sync.Snapshot["public"], after: number) {
      if (value.revision >= after) counter.set(value.value);
    },
    bootstrapPrivate(value: NonNullable<Sync.Snapshot["private"]>, after: number) {
      if (value.revision < after) return;
      profile.set(value.profile);
      todos.set(value.todos);
    },
    change(change: Sync.Change) {
      switch (change.kind) {
        case "counter":
          counter.set(change.value);
          break;
        case "profile":
          profile.set(change.profile);
          break;
        case "todos":
          todos.set(change.rows);
          break;
      }
    },
    snapshot(publicRevision: number, privateRevision: number): Sync.Snapshot {
      const saved = profile.get();
      return {
        public: { stream: "public", revision: Math.max(0, publicRevision), value: counter.get() },
        private:
          saved === null
            ? null
            : {
                stream: saved.id,
                revision: Math.max(0, privateRevision),
                profile: saved,
                todos: todos.get(),
              },
      };
    },
  }),
});

import { data } from "@tinker/core";

import type { Sync } from "~/components/sync";

import type { Profile } from "@/demo/contracts/profile-contract";
import type { Todos } from "@/demo/contracts/todos-contract";

export const profile = data<Profile.Value | null>({
  label: "profile",
  initial: null,
});

export const nameDraft = data<string | undefined>({ label: "nameDraft", initial: undefined });
export const pending = data({ label: "pending", initial: false });
